-- chair-step: inverse of read_lane_v2_b3_15_workbench_udt_documents — un-enrolls workbench.udt_documents from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'udt_documents' and is_active);
select iam.apply_rls('workbench', 'udt_documents', (select token from platform.entity_types where schema_name = 'workbench' and table_name = 'udt_documents' and is_active), (select rls_variant from platform.entity_types where schema_name = 'workbench' and table_name = 'udt_documents' and is_active));
